package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7b; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.*;
class GovernanceScaleupSemanticDistinctnessTest { @Test void newFingerprintsAreUnique() throws Exception { Map<String,Object>d=Stage7BGovernanceDatasetSupport.objectResource("/benchmark/v1/governance/scaleup/governance-root-fingerprints.json"); @SuppressWarnings("unchecked") List<Map<String,Object>> roots=(List<Map<String,Object>>)d.get("roots"); assertThat(roots).hasSize(50); assertThat(roots.stream().map(x->x.get("fingerprintHash")).distinct()).hasSize(50); }}
